"use strict";(self.webpackChunkhalt_website=self.webpackChunkhalt_website||[]).push([[88779],{2733:e=>{e.exports=JSON.parse('{"tag":{"label":"dental disease","permalink":"/docs/tags/dental-disease","allTagsPath":"/docs/tags","count":25,"items":[{"id":"Chinchillas/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Chinchillas","description":"An overview of the most common health issues affecting pet chinchillas, including dental disease, bloat, ringworm, and heat stroke, with a focus on prevention and recognizing early warning signs.","permalink":"/docs/Chinchillas/illnesses-and-conditions/common-health-issues"},{"id":"Degus/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Degus","description":"An overview of the most common health issues affecting pet degus, including their genetic predisposition to diabetes, dental disease, tail slip, and bumblefoot.","permalink":"/docs/Degus/illnesses-and-conditions/common-health-issues"},{"id":"Gerbils/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Gerbils","description":"An overview of the most common health issues affecting pet gerbils, including respiratory infections, scent gland tumors, tail slip, and Tyzzer\'s disease.","permalink":"/docs/Gerbils/illnesses-and-conditions/common-health-issues"},{"id":"Hamsters/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Hamsters","description":"An overview of the most common health issues affecting pet hamsters, including the critical emergency of wet tail, respiratory infections, and common tumors.","permalink":"/docs/Hamsters/illnesses-and-conditions/common-health-issues"},{"id":"Hedgehogs/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Hedgehogs","description":"An overview of the most common health issues affecting pet hedgehogs, including the devastating Wobbly Hedgehog Syndrome (WHS), their high incidence of cancer, and common problems like obesity and parasites.","permalink":"/docs/Hedgehogs/illnesses-and-conditions/common-health-issues"},{"id":"Mice/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Mice","description":"An overview of the most common health issues affecting pet mice, with a focus on the pervasive nature of respiratory disease (Mycoplasma), their high rate of tumors, and common parasites.","permalink":"/docs/Mice/illnesses-and-conditions/common-health-issues"},{"id":"Rabbits/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Rabbits","description":"An overview of the most common and serious health issues affecting pet rabbits, including the critical emergencies of GI stasis, the importance of dental health, and the high rate of uterine cancer in unspayed females.","permalink":"/docs/Rabbits/illnesses-and-conditions/common-health-issues"},{"id":"Rats/illnesses-and-conditions/common-health-issues","title":"Common Health Issues in Rats","description":"An overview of the most common health issues affecting pet rats, focusing on the chronic nature of Mycoplasma respiratory infections, the high incidence of mammary tumors, and conditions like bumblefoot.","permalink":"/docs/Rats/illnesses-and-conditions/common-health-issues"},{"id":"Chinchillas/illnesses-and-conditions/dental-disease-in-chinchillas","title":"Dental Disease in Chinchillas","description":"Learn about the causes, symptoms, and treatment of dental disease and malocclusion in chinchillas, including how diet and genetics play a role.","permalink":"/docs/Chinchillas/illnesses-and-conditions/dental-disease-in-chinchillas"},{"id":"guinea-pigs/health-and-wellness/dental-disease","title":"dental-disease","description":"Dental disease is one of the most common and serious health problems affecting guinea pigs. Unlike humans, a guinea pig\'s teeth grow continuously throughout their life. This continuous growth can...","permalink":"/docs/guinea-pigs/health-and-wellness/dental-disease"},{"id":"Chinchillas/health-and-wellness/dental-health","title":"dental-health","description":"A detailed guide to dental disease in chinchillas, covering the causes of malocclusion, recognizing the signs of dental problems, and the critical role of a high-hay diet in prevention.","permalink":"/docs/Chinchillas/health-and-wellness/dental-health"},{"id":"Degus/health-and-wellness/dental-health","title":"dental-health","description":"A comprehensive guide to dental disease in degus, explaining the causes of malocclusion, how to recognize the signs, and the critical importance of a proper, hay-based diet for prevention.","permalink":"/docs/Degus/health-and-wellness/dental-health"},{"id":"Ferrets/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in ferrets, covering common issues like fractured teeth and tartar buildup, and outlining the importance of preventative care, including diet and tooth brushing.","permalink":"/docs/Ferrets/health-and-wellness/dental-health"},{"id":"Gerbils/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in gerbils, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the critical role of chewing materials.","permalink":"/docs/Gerbils/health-and-wellness/dental-health"},{"id":"guinea-pigs/health-and-wellness/dental-health","title":"dental-health","description":"A detailed guide to dental disease in guinea pigs, explaining the causes of malocclusion, how to recognize the signs, and the critical role of a high-hay diet in prevention.","permalink":"/docs/guinea-pigs/health-and-wellness/dental-health"},{"id":"Hamsters/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in hamsters, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the importance of providing appropriate chew toys.","permalink":"/docs/Hamsters/health-and-wellness/dental-health"},{"id":"Hedgehogs/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in hedgehogs, covering common problems like gingivitis, tartar, fractured teeth, and the high risk of oral cancers like squamous cell carcinoma.","permalink":"/docs/Hedgehogs/health-and-wellness/dental-health"},{"id":"Mice/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in mice, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the importance of providing a proper diet and chew toys.","permalink":"/docs/Mice/health-and-wellness/dental-health"},{"id":"Rabbits/health-and-wellness/dental-health","title":"dental-health","description":"An in-depth guide to dental disease in rabbits, explaining why it is so common, how to recognize the signs of oral pain, and the absolute necessity of a hay-based diet for prevention.","permalink":"/docs/Rabbits/health-and-wellness/dental-health"},{"id":"Rats/health-and-wellness/dental-health","title":"dental-health","description":"A guide to dental health in rats, focusing on the causes and prevention of incisor overgrowth (malocclusion) and the importance of providing a proper diet and chew toys.","permalink":"/docs/Rats/health-and-wellness/dental-health"},{"id":"Rabbits/getting-started/essential-supplies-for-rabbits","title":"essential-supplies-for-rabbits","description":"Bringing a rabbit into your home is a long-term commitment, and providing the right supplies is the first step to ensuring a happy, healthy life for your new friend. Rabbits have specific needs that...","permalink":"/docs/Rabbits/getting-started/essential-supplies-for-rabbits"},{"id":"Degus/health-and-wellness/eye-and-vision-issues","title":"eye-and-vision-issues","description":"A guide to common eye and vision issues in degus, with a focus on the strong link between cataracts and diabetes, as well as other problems like eye injuries and weeping eyes from dental disease.","permalink":"/docs/Degus/health-and-wellness/eye-and-vision-issues"},{"id":"Rabbits/health-and-wellness/home-health-care-for-your-rabbit","title":"Home Health Care for Your Rabbit","description":"Caring for a rabbit can be a deeply rewarding experience, bringing joy and companionship to your home. These intelligent and social creatures, capable of living up to 12\u201315 years, thrive with proper care and attention [1]. Understanding their unique needs \u2014 from diet to dental health and disease prevention \u2014 is crucial for ensuring a long and happy life for your furry friend. This guide walks you through essential aspects of home health care for your rabbit.","permalink":"/docs/Rabbits/health-and-wellness/home-health-care-for-your-rabbit"},{"id":"Rabbits/health-and-wellness/rabbit-dental-health","title":"rabbit-dental-health","description":"Dental health is one of the most critical aspects of a rabbit\'s overall well-being. Unlike humans, a rabbit\'s teeth grow continuously throughout their life. A proper diet and regular monitoring are essential to prevent painful and life-threatening dental disease. This guide covers the fundamentals of rabbit dental anatomy, common problems, and preventative care.","permalink":"/docs/Rabbits/health-and-wellness/rabbit-dental-health"},{"id":"Rats/health-and-wellness/rat-dental-care","title":"rat-dental-care","description":"Dental health is one of the most important \u2014 and most overlooked \u2014 aspects of rat care. Because rat incisors grow continuously throughout life, they must wear down properly to prevent serious complications. A rat with dental problems will struggle to eat, lose weight rapidly, and can deteriorate quickly. Understanding how rat teeth work and how to support healthy dental wear is essential for every rat owner.","permalink":"/docs/Rats/health-and-wellness/rat-dental-care"}],"unlisted":false}}')}}]);